DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    -- Delete existing CAM 20 if any
    DELETE FROM public.topics WHERE name = 'CAM 20' AND user_id IS NULL;
    
    -- Insert CAM 20 topic
    VALUES (gen_random_uuid(), NULL, 'CAM 20', 'school', 'CAM', NOW() + interval '10 seconds')
    RETURNING id INTO v_topic_id;
    
END $$;