    INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
    (v_topic_id, 'nocturnal', '/nɒkˈtɜːnl/', '(adj) hoạt động về đêm', 'The kākāpō is a strictly nocturnal bird, venturing out into the forest almost exclusively after dark.', 'Test 1', 0, 1, NOW() + interval '10001 seconds'),
    (v_topic_id, 'flightless', '/ˈflaɪtləs/', '(adj) không biết bay', 'The study revealed a flightless aspect of modern development.', 'Test 1', 0, 2, NOW() + interval '10002 seconds'),
    (v_topic_id, 'solitary', '/ˈsɒlətri/', '(adj) sống đơn độc', 'The prisoners who started the riot were moved to solitary.', 'Test 1', 0, 3, NOW() + interval '10003 seconds'),
    (v_topic_id, 'forage', '/ˈfɒrɪdʒ/', '(v) tìm kiếm thức ăn', 'Researchers need to forage the key factors involved in this process.', 'Test 1', 0, 4, NOW() + interval '10004 seconds'),
    (v_topic_id, 'frond', '/frɒnd/', '(n) lá cây dương xỉ / lá cọ', 'The frond plays an essential role in the overall system.', 'Test 1', 0, 5, NOW() + interval '10005 seconds'),
    (v_topic_id, 'incubation', '/ˌɪŋkjuˈbeɪʃn/', '(n) sự ấp trứng', 'The incubation plays an essential role in the overall system.', 'Test 1', 0, 6, NOW() + interval '10006 seconds'),
    (v_topic_id, 'prey', '/preɪ/', '(n/v) con mồi / săn mồi', 'The prey plays an essential role in the overall system.', 'Test 1', 0, 7, NOW() + interval '10007 seconds'),
    (v_topic_id, 'coloniser', '/ˈkɒlənaɪzə(r)/', '(n) người đi khai phá / thực dân', 'The coloniser plays an essential role in the overall system.', 'Test 1', 0, 8, NOW() + interval '10008 seconds'),
    (v_topic_id, 'clearance', '/ˈklɪərəns/', '(n) sự phát quang / đốn hạ rừng', 'Uncontrolled land development and massive habitat clearance severely reduced the native forest areas available to wildlife.', 'Test 1', 0, 9, NOW() + interval '10009 seconds'),
    (v_topic_id, 'deplete', '/dɪˈpliːt/', '(v) làm kiệt quệ, tiêu hao', 'The continuous loss of low-altitude forests threatens to deplete local food supplies for ground-dwelling birds.', 'Test 1', 0, 10, NOW() + interval '10010 seconds'),
    (v_topic_id, 'stoat', '/stəʊt/', '(n) con chồn ermine (động vật ăn thịt nhỏ)', 'The stoat plays an essential role in the overall system.', 'Test 1', 0, 11, NOW() + interval '10011 seconds'),
    (v_topic_id, 'initiative', '/ɪˈnɪʃətɪv/', '(n) sáng kiến, phương án mới', 'A new conservation initiative was launched in 1996 to secure additional funding and scientific support.', 'Test 1', 0, 12, NOW() + interval '10012 seconds'),
    (v_topic_id, 'subsequent', '/ˈsʌbsɪkwənt/', '(adj) xảy ra sau đó, tiếp theo', 'Growth was dampened by a softening of the global economy in 2001, but picked up in the subsequent years due to strong growth in China.', 'Test 1', 0, 13, NOW() + interval '10013 seconds'),
    (v_topic_id, 'feral', '/ˈferəl/', '(adj) hoang dại (từ động vật nuôi bị xổng)', 'Predation by the introduced feral cat nearly wiped out the remaining kākāpō population on Rakiura Island.', 'Test 1', 0, 14, NOW() + interval '10014 seconds'),
    (v_topic_id, 'sanctuary', '/ˈsæŋktʃuəri/', '(n) khu bảo tồn, nơi trú ẩn an toàn', 'Environmentalists relocated remaining birds to an offshore island sanctuary to isolate them from mainland predators.', 'Test 1', 0, 15, NOW() + interval '10015 seconds'),
    (v_topic_id, 'offset', '/ˌɒfˈset/', '(v) bù đắp, đền bù', 'Researchers need to offset the key factors involved in this process.', 'Test 1', 0, 16, NOW() + interval '10016 seconds'),
    (v_topic_id, 'mortality', '/mɔːˈtæləti/', '(n) tỷ lệ tử vong, sự qua đời', 'High rates of adult mortality made it nearly impossible for the small population to rebuild naturally.', 'Test 1', 0, 17, NOW() + interval '10017 seconds'),
    (v_topic_id, 'prompt', '/prɒmpt/', '(v) thúc đẩy, xúi giục, gây', 'I filled in my name where the prompt appeared on the computer screen but my account wasn''t recognized.', 'Test 1', 0, 18, NOW() + interval '10018 seconds'),
    (v_topic_id, 'eradicate', '/ɪˈrædɪkeɪt/', '(v) tiêu diệt tận gốc, xóa bỏ', 'To protect vulnerable chicks, conservation teams worked tirelessly to eradicate all invasive rats from the island.', 'Test 1', 0, 19, NOW() + interval '10019 seconds'),
