    (v_topic_id, 'accommodate', '/əˈkɒmədeɪt/', '(v) cung cấp chỗ ở / đáp ứng nhu cầu', 'Researchers need to accommodate the key factors involved in this process.', 'Test 1', 0, 22, NOW() + interval '10022 seconds'),
    (v_topic_id, 'stakeholder', '/ˈsteɪkhəʊldə(r)/', '(n) bên liên quan, các bên hợp tác', 'The stakeholder plays an essential role in the overall system.', 'Test 1', 0, 23, NOW() + interval '10023 seconds'),
    (v_topic_id, 'diversity', '/daɪˈvɜːsəti/', '(n) sự đa dạng', 'Protecting a tiny surviving population poses challenges in maintaining adequate levels of genetic diversity.', 'Test 1', 0, 24, NOW() + interval '10024 seconds'),
    (v_topic_id, 'vulnerable', '/ˈvʌlnərəbl/', '(adj) dễ bị tổn thương, nguy cấp', 'To protect vulnerable chicks, conservation teams worked tirelessly to eradicate all invasive rats from the island.', 'Test 1', 0, 25, NOW() + interval '10025 seconds'),
    (v_topic_id, 'Critically endangered', '', 'Cực kỳ nguy cấp (trên đà tuyệt chủng)', 'The kākāpō is officially classified as a critically endangered bird species due to severe historical population losses.', 'Test 1', 0, 26, NOW() + interval '10026 seconds'),
    (v_topic_id, 'Flightless parrot', '', 'Loài vẹt không biết bay', 'The evidence clearly demonstrates that Flightless parrot.', 'Test 1', 0, 27, NOW() + interval '10027 seconds'),
    (v_topic_id, 'Habitat clearance', '', 'Sự phát quang / tàn phá môi trường sống', 'Uncontrolled land development and massive habitat clearance severely reduced the native forest areas available to wildlife.', 'Test 1', 0, 28, NOW() + interval '10028 seconds'),
