    (v_topic_id, 'Island sanctuary', '', 'Khu bảo tồn trên đảo', 'Environmentalists relocated remaining birds to an offshore island sanctuary to isolate them from mainland predators.', 'Test 1', 0, 30, NOW() + interval '10030 seconds'),
