    (v_topic_id, 'Cautious optimism', '', 'Sự lạc quan thận trọng', 'Ecologists maintain a sense of cautious optimism following recent increases in chick survival rates.', 'Test 1', 0, 32, NOW() + interval '10032 seconds'),
    (v_topic_id, 'Genetic diversity', '', 'Sự đa dạng di truyền', 'Protecting a tiny surviving population poses challenges in maintaining adequate levels of genetic diversity.', 'Test 1', 0, 33, NOW() + interval '10033 seconds'),
    (v_topic_id, 'Predator-free island', '', 'Hòn đảo không có động vật ăn thịt', 'The project aims to Predator-free island for sustainable development.', 'Test 1', 0, 34, NOW() + interval '10034 seconds'),
    (v_topic_id, 'Supplementary feeding', '', 'Việc cung cấp thức ăn bổ sung', 'Field workers provided essential supplementary feeding to ensure breeding females remained healthy during food shortages.', 'Test 1', 0, 35, NOW() + interval '10035 seconds'),
    (v_topic_id, 'Feral cat', '', 'Mèo hoang (mèo nhà xổng ra ngoài tự nhiên)', 'Predation by the introduced feral cat nearly wiped out the remaining kākāpō population on Rakiura Island.', 'Test 1', 0, 36, NOW() + interval '10036 seconds'),
    (v_topic_id, 'Urgent review', '', 'Sự đánh giá / rà soát khẩn cấp', 'Government authorities ordered an urgent review of current wildlife preservation strategies after numbers dropped to 51.', 'Test 1', 0, 37, NOW() + interval '10037 seconds'),
    (v_topic_id, 'reintroduce', '/ˌriːɪntrəˈdjuːs /', '(v) tái nhập, đưa trở lại tự nhiên', 'Researchers need to reintroduce the key factors involved in this process.', 'Test 1', 0, 38, NOW() + interval '10038 seconds'),
    (v_topic_id, 'aftermath', '/ˈɑːftəmæθ/', '(n) hậu quả, giai đoạn sau thảm họa', 'In contrast to most projections of the aftermath of nuclear war, in this there is no rioting or looting.', 'Test 1', 0, 39, NOW() + interval '10039 seconds'),
    (v_topic_id, 'vascular', '/ˈvæskjələ(r)/', '(adj) thuộc về mạch (dẫn nước, dinh dưỡng)', 'The parasitic fungus attacks and clogs the tree’s vascular system, preventing necessary fluids from reaching upper branches.', 'Test 1', 0, 40, NOW() + interval '10040 seconds'),
