    (v_topic_id, 'virulent', '/ˈvɪrələnt/', '(adj) rất độc, độc hại, lây lan mạnh', 'The second wave of infection proved far more lethal because beetles carried a highly virulent strain.', 'Test 1', 0, 43, NOW() + interval '10043 seconds'),
    (v_topic_id, 'strain', '/streɪn/', '(n) chủng (vi khuẩn, nấm,', 'The second wave of infection proved far more lethal because beetles carried a highly virulent strain.', 'Test 1', 0, 44, NOW() + interval '10044 seconds'),
