    (v_topic_id, 'ingrained', '/ˌɪnˈɡreɪnd/', '(adj) ăn sâu vào, gắn liền', 'The dirt was deeply ingrained in the carpet.', 'Test 1', 0, 48, NOW() + interval '10048 seconds'),
    (v_topic_id, 'advocate', '/ˈædvəkət/', '(n/v) người ủng hộ / công khai ủng hộ', 'Since she started working with her advocate, she has become much more confident.', 'Test 1', 0, 49, NOW() + interval '10049 seconds'),
