    (v_topic_id, 'Hyper-vigilant state', '', 'Trạng thái cảnh giác cao độ', 'Under high pressure, firefighters enter a hyper-vigilant state where they process negative information far more effectively.', 'Test 1', 0, 101, NOW() + interval '10101 seconds'),
    (v_topic_id, 'Cortisol level', '', 'Nồng độ hormone stress (cortisol)', 'Experimental subjects exposed to threatening scenarios experienced a sudden spike in their blood cortisol level.', 'Test 1', 0, 102, NOW() + interval '10102 seconds'),
    (v_topic_id, 'Neural signal', '', 'Tín hiệu thần kinh', 'The brain uses a rapid neural signal to alter how an individual evaluates potential environmental hazards.', 'Test 1', 0, 103, NOW() + interval '10103 seconds'),
    (v_topic_id, 'Collective fear', '', 'Nỗi sợ hãi tập thể / đám đông', 'Sensationalized news reporting after a natural disaster often fuels irrational, widespread collective fear.', 'Test 1', 0, 104, NOW() + interval '10104 seconds'),
    (v_topic_id, 'Stress reaction', '', 'Phản ứng căng thẳng', 'High-stress environments trigger a intense stress reaction that heightens a person''s sensitivity to bad news.', 'Test 1', 0, 105, NOW() + interval '10105 seconds'),
    (v_topic_id, 'Warning sign', '', 'Dấu hiệu cảnh báo', 'Brain imaging scans demonstrate that processing a sudden warning sign relies on specific pathways in the neural network.', 'Test 1', 0, 106, NOW() + interval '10106 seconds'),
    (v_topic_id, 'Public speech', '', 'Bài phát biểu trước công chúng', 'Participants forced to give an unexpected public speech exhibited a rapid increase in heart rate and stress hormones.', 'Test 1', 0, 107, NOW() + interval '10107 seconds'),
    (v_topic_id, 'Social media feed', '', 'Bảng tin mạng xã hội', 'Regularly scrolling through a negative social media feed can inadvertently raise a person''s pulse and anxiety levels. Compiled by CheeseNOTES 🧀', 'Test 1', 0, 108, NOW() + interval '10108 seconds'),
    (v_topic_id, 'Physiological reaction', '', 'Phản ứng sinh lý cơ thể', 'Evolutionary biology suggests that an automatic physiological reaction helped early humans escape dangerous wild animals.', 'Test 1', 0, 109, NOW() + interval '10109 seconds'),
    (v_topic_id, 'Famished predator', '', 'Động vật săn mồi đang đói khát', 'The evidence clearly demonstrates that Famished predator.', 'Test 1', 0, 110, NOW() + interval '10110 seconds'),
    (v_topic_id, 'Agent of change', '', 'Nhân tố / Tác nhân tạo ra sự thay đổi', 'Empathetic leaders who understand psychological stress can frame messages effectively to become an active agent of change.', 'Test 1', 0, 111, NOW() + interval '10111 seconds');
